package ua.malinapk.birthdays;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;import java.time.*;import java.util.*;
public class ReminderReceiver extends BroadcastReceiver {
 static final String CHANNEL="birthdays", ACTION="ua.malinapk.birthdays.REMINDER";
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("birthday",0);}
 static void cache(Context c,List<Person> list)throws Exception{JSONArray a=new JSONArray();for(Person p:list)a.put(p.json());prefs(c).edit().putString("cache",a.toString()).apply();}
 static List<Person> cached(Context c){List<Person> p=new ArrayList<>();try{JSONArray a=new JSONArray(prefs(c).getString("cache","[]"));for(int i=0;i<a.length();i++)p.add(Person.from(a.getJSONObject(i)));}catch(Exception ignored){}return p;}
 static void channel(Context c){NotificationChannel n=new NotificationChannel(CHANNEL,"Дні народження",NotificationManager.IMPORTANCE_HIGH);n.setDescription("Нагадування про іменинників підприємства");c.getSystemService(NotificationManager.class).createNotificationChannel(n);}
 static PendingIntent alarm(Context c,int offset){Intent i=new Intent(c,ReminderReceiver.class).setAction(ACTION).putExtra("offset",offset);return PendingIntent.getBroadcast(c,offset,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static LocalTime time(Context c,int o){return LocalTime.of(prefs(c).getInt("hour"+o,8),prefs(c).getInt("minute"+o,0));}
 static void schedule(Context c){for(int o=0;o<=2;o++)scheduleOne(c,o);}
 static void scheduleOne(Context c,int o){AlarmManager am=c.getSystemService(AlarmManager.class);LocalDateTime now=LocalDateTime.now();PendingIntent pi=alarm(c,o);am.cancel(pi);if(!prefs(c).getBoolean("enabled"+o,true))return;LocalDateTime next=LocalDateTime.of(now.toLocalDate(),time(c,o));if(!next.isAfter(now))next=next.plusDays(1);long when=next.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();try{if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);}}
 static List<Person> current(Context c){try{String u=prefs(c).getString("uri","");if(!u.isEmpty()){java.io.InputStream in=c.getContentResolver().openInputStream(Uri.parse(u));if(in!=null){Workbook w=new Workbook(Workbook.bytes(in));cache(c,w.people);return w.people;}}}catch(Exception ignored){}return cached(c);}
 static void notify(Context c,String title,String text,int id){channel(c);Intent i=new Intent(c,MainActivity.class);PendingIntent open=PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_menu_my_calendar).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setAutoCancel(true).setContentIntent(open).build();try{c.getSystemService(NotificationManager.class).notify(id,n);}catch(SecurityException ignored){}}
 @Override public void onReceive(Context c,Intent i){if(ACTION.equals(i.getAction())){int offset=i.getIntExtra("offset",0);if(prefs(c).getBoolean("enabled"+offset,true)){String date=LocalDate.now().toString();String key="last"+offset; if(!date.equals(prefs(c).getString(key,""))){List<Person> list=current(c);LocalDate target=LocalDate.now().plusDays(offset);int yr=target.getYear();for(Person p:list){if(p.birthday(yr).equals(target)&&(!prefs(c).getBoolean("onlyJubilee",false)||p.jubilee(yr))){String title=(offset==0?"Сьогодні":offset==1?"Завтра":"Через два дні")+ (p.jubilee(yr)?" — ювілей!":" — день народження!");notify(c,title,p.name()+"\n"+(offset==0?"Виповнилося ":"Виповниться ")+p.ageIn(yr)+" р.",Math.abs(Objects.hash(p.name(),p.born,offset,target)));}}prefs(c).edit().putString(key,date).apply();}}scheduleOne(c,offset);}else schedule(c);}
}
